import os
import torch
import numpy as np
import random


class Config:
    # ==== File Paths ====
    INPUT_DIR = "./input"
    WORKING_DIR = "./working"
    METADATA_DIR = "./metadata"

    # BSON Files
    TRAIN_BSON = os.path.join(INPUT_DIR, "train.bson")
    TEST_BSON = os.path.join(INPUT_DIR, "test.bson")

    # Metadata Files (Generated by previous steps)
    TRAIN_META = os.path.join(METADATA_DIR, "train.csv")
    VAL_META = os.path.join(METADATA_DIR, "val.csv")
    TEST_META = os.path.join(METADATA_DIR, "test.csv")
    CATEGORY_NAMES = os.path.join(INPUT_DIR, "category_names.csv")

    # Output Directories
    IDEA_DIR = os.path.join(WORKING_DIR, "idea_3")
    CHECKPOINT_DIR = os.path.join(IDEA_DIR, "checkpoints")
    LOG_DIR = os.path.join(IDEA_DIR, "logs")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure directories exist
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(LOG_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # ==== Model Settings ====
    ARCH = "resnet50"
    NUM_CLASSES = 5270
    PRETRAINED = True
    DROPOUT = (
        0.0  # ResNet usually doesn't use dropout before the final fc, but can be added
    )

    # ==== Data Settings ====
    # Image size: 180x180 is the native size in BSON.
    # ResNet usually expects 224x224. We can resize or train at 180.
    # Training at 180 is faster. Let's use 180 or slight upscale.
    IMG_SIZE = 180
    INPUT_SIZE = 224  # Standard ResNet input

    # Normalization (ImageNet defaults)
    MEAN = [0.485, 0.456, 0.406]
    STD = [0.229, 0.224, 0.225]

    # ==== Training Hyperparameters ====
    SEED = 42
    BATCH_SIZE = 256  # Adjusted for A100 40GB with ResNet50
    EPOCHS = 2  # As per strategy

    # Optimizer & Scheduler
    LR_MAX = 1e-2  # Peak LR for OneCycle
    WEIGHT_DECAY = 1e-4
    MOMENTUM = 0.9

    # Regularization
    MIXUP_ALPHA = 0.2  # Beta distribution parameter for Mixup
    LABEL_SMOOTHING = 0.1  # Label smoothing factor

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 8  # 12 vCPUs available, leave some for overhead
    PIN_MEMORY = True

    # AMP (Automatic Mixed Precision)
    USE_AMP = True

    # ==== Debugging / Development ====
    # Set DEBUG to True to run on a small subset of data for quick testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 50000

    @staticmethod
    def seed_everything(seed=42):
        """
        Sets the random seed for Python, NumPy, and PyTorch to ensure reproducibility.
        """
        random.seed(seed)
        os.environ["PYTHONHASHSEED"] = str(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = (
            True  # False for strict reproducibility, True for speed
        )
